#define FORWARD_BUTTON 13
#define REVERSE_BUTTON 12
#define LEFT_BUTTON    14
#define RIGHT_BUTTON   27
#define STOP_BUTTON    26
#define TURBO_BUTTON   25

void setup() {
  Serial.begin(115200);

  pinMode(FORWARD_BUTTON, INPUT_PULLUP);
  pinMode(REVERSE_BUTTON, INPUT_PULLUP);
  pinMode(LEFT_BUTTON, INPUT_PULLUP);
  pinMode(RIGHT_BUTTON, INPUT_PULLUP);
  pinMode(STOP_BUTTON, INPUT_PULLUP);
  pinMode(TURBO_BUTTON, INPUT_PULLUP);

  Serial.println();
  Serial.println("==============================");
  Serial.println("CONTROLLER BUTTON TEST");
  Serial.println("==============================");
  Serial.println("Press a button...");
}

void loop() {

  if (digitalRead(FORWARD_BUTTON) == LOW) {
    Serial.println("FORWARD");
  }
  else if (digitalRead(REVERSE_BUTTON) == LOW) {
    Serial.println("REVERSE");
  }
  else if (digitalRead(LEFT_BUTTON) == LOW) {
    Serial.println("LEFT");
  }
  else if (digitalRead(RIGHT_BUTTON) == LOW) {
    Serial.println("RIGHT");
  }
  else if (digitalRead(STOP_BUTTON) == LOW) {
    Serial.println("STOP");
  }
  else if (digitalRead(TURBO_BUTTON) == LOW) {
    Serial.println("TURBO");
  }

  delay(200);
}
